#include <bits/stdc++.h>
using namespace std;
int a[5];
int b[5];
int main(){
	int n;
	cin>>n;
	int minV=INT_MAX;
	for(int i=1;i<=3;i++){
		cin>>a[i]>>b[i];
	}
	for(int i=1;i<=3;i++){
		int t=0;
		if(n%a[i]==0) t=n/a[i]*b[i];
		else t=(n/a[i]+1)*b[i];
		minV=min(minV,t);
	}
	cout<<minV;
	return 0;
}
